// The world map's geometry, generated once from Natural Earth (public domain): the 110m
// land outline (via world-atlas) projected equirectangularly into a 360x180 box
// (x = longitude + 180, y = 90 - latitude), and each country's label point from the 50m
// admin-0 set, with the few small territories that set omits filled in by hand. Static
// data: regenerate rather than edit if the outline ever needs more detail.

/** A latitude/longitude as a point in the same 360x180 box LAND_PATH is drawn in. */
export function projectToMap(lat: number, lng: number): { x: number; y: number } {
  return { x: lng + 180, y: 90 - lat };
}

